package com.example.smartmartimport android.os.Bundleimport android.util.Logimport androidx.activity.ComponentActivityimport androidx.activity.compose.setContentimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.PaddingValuesimport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.lazy.LazyColumnimport androidx.compose.foundation.lazy.itemsimport androidx.compose.material3.Buttonimport androidx.compose.material3.Cardimport androidx.compose.material3.CircularProgressIndicatorimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Scaffoldimport androidx.compose.material3.Textimport androidx.compose.material3.TextButtonimport androidx.compose.runtime.Composableimport androidx.compose.runtime.LaunchedEffectimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableIntStateOfimport androidx.compose.runtime.mutableStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.setValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.unit.dpimport com.example.smartmart.ui.theme.SmartMartThemeimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.withContextimport org.json.JSONArrayimport java.net.HttpURLConnectionimport java.net.Proxyimport java.net.URLimport java.text.NumberFormatimport java.util.Localedata class Product(    val productId: Long,    val productName: String,    val sku: String,    val unit: String,    val price: Double,    val isActive: Boolean)class MainActivity : ComponentActivity() {    override fun onCreate(savedInstanceState: Bundle?) {        super.onCreate(savedInstanceState)        setContent {            SmartMartTheme {                SmartMartScreen()            }        }    }}// Gọi API trên luồng IO, không cập nhật UI tại đây.private suspend fun fetchProducts(): List<Product> =    withContext(Dispatchers.IO) {        val connection = URL(            "http://127.0.0.1:8080/api/products"        ).openConnection(Proxy.NO_PROXY) as HttpURLConnection        try {            connection.requestMethod = "GET"            connection.connectTimeout = 10000            connection.readTimeout = 10000            val statusCode = connection.responseCode            if (statusCode !in 200..299) {                throw IllegalStateException(                    "Server trả về mã lỗi HTTP $statusCode"                )            }            val response = connection.inputStream                .bufferedReader()                .use { it.readText() }            val jsonArray = JSONArray(response)            List(jsonArray.length()) { index ->                val item = jsonArray.getJSONObject(index)                Product(                    productId = item.getLong("productId"),                    productName = item.optString(                        "productName", "Chưa có tên"                    ),                    sku = item.optString("sku", ""),                    unit = item.optString("unit", ""),                    price = item.optDouble("price", 0.0),                    isActive = item.optBoolean("isActive", true)                )            }        } finally {            connection.disconnect()        }    }@Composablefun SmartMartScreen() {    var products by remember {        mutableStateOf<List<Product>>(emptyList())    }    var loading by remember {        mutableStateOf(true)    }    var error by remember {        mutableStateOf<String?>(null)    }    // Tăng giá trị này mỗi khi người dùng muốn tải lại.    var refreshKey by remember {        mutableIntStateOf(0)    }    LaunchedEffect(refreshKey) {        loading = true        error = null        try {            products = fetchProducts()        } catch (e: Exception) {            Log.e(                "SMARTMART_API",                "Loi khi tai danh sach san pham",                e            )            error = "Không thể tải sản phẩm: " +                    (e.localizedMessage ?: "Lỗi không xác định")        } finally {            loading = false        }    }    Scaffold(        modifier = Modifier.fillMaxSize(),        topBar = {            Column(                modifier = Modifier                    .fillMaxWidth()                    .padding(16.dp)            ) {                Text(                    text = "SmartMart",                    style = MaterialTheme.typography.headlineMedium                )                Row(                    modifier = Modifier.fillMaxWidth(),                    horizontalArrangement = Arrangement.SpaceBetween,                    verticalAlignment = Alignment.CenterVertically                ) {                    Text(                        text = "Danh sách sản phẩm",                        style = MaterialTheme.typography.titleMedium                    )                    TextButton(                        onClick = { refreshKey++ },                        enabled = !loading                    ) {                        Text("Làm mới")                    }                }                if (!loading && error == null) {                    Text(                        text = "Tổng số: ${products.size} sản phẩm",                        style = MaterialTheme.typography.bodySmall                    )                }            }        }    ) { innerPadding ->        when {            loading -> {                Column(                    modifier = Modifier                        .fillMaxSize()                        .padding(innerPadding),                    verticalArrangement = Arrangement.Center,                    horizontalAlignment = Alignment.CenterHorizontally                ) {                    CircularProgressIndicator()                    Text(                        text = "Đang tải sản phẩm...",                        modifier = Modifier.padding(16.dp)                    )                }            }            error != null -> {                Column(                    modifier = Modifier                        .fillMaxSize()                        .padding(innerPadding)                        .padding(16.dp),                    verticalArrangement = Arrangement.Center,                    horizontalAlignment = Alignment.CenterHorizontally                ) {                    Text(                        text = error ?: "Đã xảy ra lỗi",                        color = MaterialTheme.colorScheme.error                    )                    Button(                        onClick = { refreshKey++ },                        modifier = Modifier.padding(top = 16.dp)                    ) {                        Text("Thử lại")                    }                }            }            products.isEmpty() -> {                Column(                    modifier = Modifier                        .fillMaxSize()                        .padding(innerPadding),                    verticalArrangement = Arrangement.Center,                    horizontalAlignment = Alignment.CenterHorizontally                ) {                    Text("Chưa có sản phẩm nào.")                }            }            else -> {                LazyColumn(                    modifier = Modifier                        .fillMaxSize()                        .padding(innerPadding),                    contentPadding = PaddingValues(16.dp),                    verticalArrangement = Arrangement.spacedBy(12.dp)                ) {                    items(                        items = products,                        key = { it.productId }                    ) { product ->                        ProductCard(product)                    }                }            }        }    }}@Composableprivate fun ProductCard(product: Product) {    val formatter = remember {        NumberFormat.getNumberInstance(            Locale.forLanguageTag("vi-VN")        ).apply {            maximumFractionDigits = 0        }    }    Card(        modifier = Modifier.fillMaxWidth()    ) {        Column(            modifier = Modifier.padding(16.dp),            verticalArrangement = Arrangement.spacedBy(6.dp)        ) {            Text(                text = product.productName,                style = MaterialTheme.typography.titleMedium            )            Text("Mã sản phẩm: ${product.sku}")            Text("Đơn vị: ${product.unit}")            Text(                text = "Giá: ${formatter.format(product.price)} đ",                style = MaterialTheme.typography.bodyLarge            )            Text(                text = if (product.isActive) {                    "Đang kinh doanh"                } else {                    "Ngừng kinh doanh"                },                color = if (product.isActive) {                    MaterialTheme.colorScheme.primary                } else {                    MaterialTheme.colorScheme.error                }            )        }    }}